class Solution:
    def minSwaps(self, nums: List[int], forbidden: List[int]) -> int:
        from collections import Counter
        n = len(nums)
        conf = [i for i in range(n) if nums[i] == forbidden[i]]
        S = len(conf)
        if S == 0:
            return 0
        fc = Counter(forbidden[i] for i in conf)
        cnt = Counter(nums)
        for v, c in fc.items():
            if c > n - cnt.get(v, 0):
                return -1
        maxC = max(fc.values())
        vstar = max(fc, key=fc.get)
        pairs = min(S // 2, S - maxC)
        singles = S - 2 * pairs
        avail = sum(1 for j in range(n)
                    if nums[j] != forbidden[j] and nums[j] != vstar and forbidden[j] != vstar)
        if singles > avail:
            return -1
        return S - pairs

