class Solution {
public:
    int minSwaps(vector<int>& nums, vector<int>& forbidden) {
        int n = nums.size(), S = 0;
        unordered_map<int,int> fc, cnt;
        int vstar = 0, maxC = 0;
        for (int i = 0; i < n; i++) cnt[nums[i]]++;
        for (int i = 0; i < n; i++) if (nums[i] == forbidden[i]) {
            S++; fc[forbidden[i]]++;
            if (fc[forbidden[i]] > maxC) { maxC = fc[forbidden[i]]; vstar = forbidden[i]; }
        }
        if (S == 0) return 0;
        for (auto& [v, c] : fc)
            if ((long long)c > n - cnt[v]) return -1;
        int pairs = min(S / 2, S - maxC);
        int singles = S - 2 * pairs;
        int avail = 0;
        for (int j = 0; j < n; j++)
            if (nums[j] != forbidden[j] && nums[j] != vstar && forbidden[j] != vstar) avail++;
        if (singles > avail) return -1;
        return S - pairs;
    }
};

