class Solution {
    public int minSwaps(int[] nums, int[] forbidden) {
        int n = nums.length, S = 0;
        Map<Integer, Integer> fc = new HashMap<>(), cnt = new HashMap<>();
        int vstar = 0, maxC = 0;
        for (int x : nums) cnt.merge(x, 1, Integer::sum);
        for (int i = 0; i < n; i++) if (nums[i] == forbidden[i]) {
            S++;
            int c = fc.merge(forbidden[i], 1, Integer::sum);
            if (c > maxC) { maxC = c; vstar = forbidden[i]; }
        }
        if (S == 0) return 0;
        for (Map.Entry<Integer, Integer> en : fc.entrySet())
            if (en.getValue() > n - cnt.getOrDefault(en.getKey(), 0)) return -1;
        int pairs = Math.min(S / 2, S - maxC);
        int singles = S - 2 * pairs;
        int avail = 0;
        for (int j = 0; j < n; j++)
            if (nums[j] != forbidden[j] && nums[j] != vstar && forbidden[j] != vstar) avail++;
        if (singles > avail) return -1;
        return S - pairs;
    }
}

