var minSwaps = function(nums, forbidden) {
    const n = nums.length;
    let S = 0;
    const fc = new Map(), cnt = new Map();
    let vstar = 0, maxC = 0;
    for (const x of nums) cnt.set(x, (cnt.get(x) || 0) + 1);
    for (let i = 0; i < n; i++) if (nums[i] === forbidden[i]) {
        S++;
        const c = (fc.get(forbidden[i]) || 0) + 1;
        fc.set(forbidden[i], c);
        if (c > maxC) { maxC = c; vstar = forbidden[i]; }
    }
    if (S === 0) return 0;
    for (const [v, c] of fc)
        if (c > n - (cnt.get(v) || 0)) return -1;
    const pairs = Math.min(Math.floor(S / 2), S - maxC);
    const singles = S - 2 * pairs;
    let avail = 0;
    for (let j = 0; j < n; j++)
        if (nums[j] !== forbidden[j] && nums[j] !== vstar && forbidden[j] !== vstar) avail++;
    if (singles > avail) return -1;
    return S - pairs;
};
